@startuml

class PERSON {
  + name_first : string
  + name_last : string
  + address : string
}

class WORKER extends PERSON {
  + birth_date : date
}

class CLIENT extends PERSON {
  + phone_number : string
  + contact_person : string
}

class SKILL {
  + name : string
}

class MACHINE {
  + serial_number : string
  + make : string
  + model : string
  + purchase_date : date
}

class PRODUCT_TYPE {
  + material : string
  + weight : float
}

class PRODUCT {
  + id : string
}

class PURCHASEORDER {
  + order_number : string
  + date_made : date
  + expected_delivery_date : date
  + actual_delivery_date : date
}

class PRODUCTPURCHASEORDER {
  + quantity : int
}

WORKER "*" -- "*" SKILL
WORKER "*" -- "*" MACHINE
MACHINE "1" -- "*" PRODUCT_TYPE
PRODUCT_TYPE "1" -- "*" PRODUCT
CLIENT "1" -- "*" PURCHASEORDER
PURCHASEORDER "1" -- "*" PRODUCTPURCHASEORDER
PRODUCT "1" -- "*" PRODUCTPURCHASEORDER

@enduml

